static final class Stack<T> {
    private final T[] items;
    private int count;

    Stack(int capacity) {
        items = new T[capacity];
    }

    void push(T item) {
        items[count++] = item;
    }

    T pop() {
        return items[--count];
    }

    T peek() {
        return items[count - 1];
    }

    int size() {
        return count;
    }

    boolean isEmpty() {
        return count == 0;
    }
}

